function countTreeShapes(n: number): number {
  const memo = new Map<number, number>();
  const shapes = (m: number): number => {
    if (m <= 1) return 1;
    if (memo.has(m)) return memo.get(m)!;
    let total = 0;
    for (let left = 0; left < m; left++) total += shapes(left) * shapes(m - 1 - left);
    memo.set(m, total);
    return total;
  };
  return shapes(n);
}

