function countTreeShapes(n: number): number {
  const count = new Array(n + 1).fill(0);
  count[0] = 1;
  for (let m = 1; m <= n; m++) {
    for (let left = 0; left < m; left++) count[m] += count[left] * count[m - 1 - left];
  }
  return count[n];
}

